/*
  # Importar ejercicios de gimnasio relevantes para futbol desde ExerciseGymGifsDB

  866 ejercicios (de los 1323 del repo) filtrados a los grupos musculares
  relevantes para un futbolista (piernas, gluteos, core, cardio, espalda/
  dorsal, hombro, antebrazo), excluyendo aislamiento puro de biceps/triceps/
  pectorales/omoplato tipico de culturismo.

  Duracion y beneficio son plantillas genericas por tipo de ejercicio (el
  repo no trae esos campos); la descripcion son las instrucciones reales
  traducidas del repo. equipment y muscle son columnas nuevas para el
  filtro de busqueda en la app.
*/

ALTER TABLE exercises ADD COLUMN IF NOT EXISTS equipment text;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS muscle text;







